# read only: where the rest outside the rim is (AI-operated)
P_ = zz_w().points(0); U_ = zz_uv(); hc_, hr_ = bc_wall(zz_hb())
B_ = np.array([zz_to_rf(q_xyz) for q_xyz in P_])
rr_ = np.linalg.norm(P_[:, :2] - hc_, axis=1)
o_ = np.flatnonzero(rr_ > hr_)
print("outside n", len(o_), "uv lo/hi", np.round(U_[o_].min(0), 2).tolist(), np.round(U_[o_].max(0), 2).tolist(), "z lo/hi", round(float(P_[o_, 2].min()), 3), round(float(P_[o_, 2].max()), 3), "rf lo/hi", np.round(B_[o_].min(0), 3).tolist(), np.round(B_[o_].max(0), 3).tolist(), flush=True)
ang_ = np.degrees(np.arctan2(P_[o_, 1] - hc_[1], P_[o_, 0] - hc_[0]))
print("outside angle about the hamper centre (deg, 0 = east, 90 = north) lo/hi", round(float(ang_.min()), 1), round(float(ang_.max()), 1), "r max", round(float(rr_[o_].max()), 3), flush=True)
for uv_ in ((0.5, -0.375), (0.5, -0.2), (0.5, 0.0), (0.5, 0.2), (0.5, 0.375), (0.4, -0.375), (0.3, -0.375), (0.2, -0.375), (0.4, -0.2), (0.3, -0.2), (-0.5, 0.0), (-0.5, -0.375), (-0.5, 0.375)):
    i_ = int(np.argmin(np.linalg.norm(U_ - np.array(uv_), axis=1)))
    print("uv", uv_, "idx", i_, "rf", np.round(B_[i_], 3).tolist(), "r", round(float(rr_[i_]), 3), flush=True)
print("fold target", bc_fold_target(zz_BL, zz_hb()), "lowest", round(float(P_[:, 2].min()), 3), "top", round(float(P_[:, 2].max()), 3), flush=True)
print("pads rf", {s_: np.round(zz_to_rf(pad_mid(s_)), 3).tolist() for s_ in SIDES}, "tilt", round(pelvis_tilt(), 3), "knees", zz_knees(), "pelvis", state()["pelvis"], flush=True)
print("look", zz_look(np.array([hc_[0], hc_[1], 0.75]), "g12", dist=1.3, h=0.6, dirs=(20.0, 160.0, 100.0), top=True), flush=True)
